+type StdoutSnapshot = (
+    rustix::fs::OFlags,
+    Result<
+        (
+            rustix::fs::OFlags,
+            (Duration, Duration),
+            Result<Vec<u8>, rustix::io::Errno>,
+        ),
+        String,
+    >,
+    Result<rustix::fs::OFlags, String>,
+);
+
+// A timeout diagnostic only: one capped, nonblocking read, then restore flags.
+// Probe or restoration errors remain evidence; the original timeout still fails.
+fn stdout_now(stdout: &impl std::os::fd::AsFd, since: Instant) -> io::Result<StdoutSnapshot> {
+    let before = rustix::fs::fcntl_getfl(stdout)?;
+    let sample = (|| -> io::Result<_> {
+        rustix::fs::fcntl_setfl(stdout, before | rustix::fs::OFlags::NONBLOCK)?;
+        let after = rustix::fs::fcntl_getfl(stdout)?;
+        if !after.contains(rustix::fs::OFlags::NONBLOCK) {
+            return Err(io::Error::other("stdout remained blocking"));
+        }
+        let mut buffer = [0_u8; 128];
+        let read_started = since.elapsed();
+        let read = rustix::io::read(stdout, &mut buffer).map(|count| buffer[..count].to_vec());
+        let read_finished = since.elapsed();
+        Ok((after, (read_started, read_finished), read))
+    })()
+    .map_err(|error| error.to_string());
+    // Run restoration even if setting/verifying NONBLOCK or reading failed.
+    let restored = (|| -> io::Result<_> {
+        rustix::fs::fcntl_setfl(stdout, before)?;
+        let after = rustix::fs::fcntl_getfl(stdout)?;
+        if after != before {
+            return Err(io::Error::other("stdout flags did not restore exactly"));
+        }
+        Ok(after)
+    })()
+    .map_err(|error| error.to_string());
+    Ok((before, sample, restored))
 }

